   "  const libro = XLSX.utils.book_new();\n  XLSX.utils.book_append_sheet(libro, hoja, nombreHoja);\n  XLSX.writeFile(libro, `${nombreArchivo}_${new Date().toISOString().slice(0,10)}.xlsx`);\n}\n\n// Reportes de Microsip en Excel (botón \"📥 Reportes Microsip\" del Dashboard).\nfunction abrirReportesMicrosip() {\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2>📥 Reportes de Microsip en Excel</h2>\n    <p style=\"font-size:12px; color:var(--muted);\">Se consultan en vivo en Microsip; los grandes pueden tardar un poco.</p>\n    <button class=\"primary\" style=\"width:100%; margin:8px 0;\" onclick=\"exportarClientesMicrosipExcel(this)\">👥 Todos los clientes (datos, última compra, estado y municipio)</button>\n    <p style=\"font-size:11px; color:var(--muted); margin:-2px 0 12px;\">El estado y municipio se toman de su dirección; si no tiene, de la lada de su teléfono.</p>\n    <button class=\"secondary\" style=\"width:100%; margin:8px 0;\" onclick=\"exportarSinClasificadorExcel(this)\">📦 Artículos sin marca / proveedor</button>\n  `;\n  abrirModal('admin');\n}\n\nasync function exportarClientesMicrosipExcel(btn) {\n  if (typeof XLSX === 'undefined') {\n    alert('No se pudo cargar el generador de Excel — revisa tu conexión e intenta de nuevo.');\n    return;\n  }\n  const original = btn ? btn.textContent : '';\n  if (btn) { btn.disabled = true; btn.textContent = 'Consultando Microsip…'; }\n  try {\n    const { clientes } = await api('/api/dashboard/clientes-microsip');\n    if (!clientes.length) { alert('Microsip no regresó clientes.'); return; }\n    // Encabezados: todos los que aparezcan, en el orden del primero que los trae.\n    const encabezados = [];\n    clientes.forEach(c => Object.keys(c).forEach(k => { if (!encabezados.includes(k)) encabezados.push(k); }));\n    const hoja = XLSX.utils.json_to_sheet(clientes, { header: encabezados });\n    hoja['!cols'] = encabezados.map(h => ({ wch: h === 'Cliente' ? 42 : h === 'ESTADO' || h === 'MUNICIPIO' ? 22 : Math.max(12, Math.min(30, h.length + 2)) }));\n    hoja['!autofilter'] = { ref: hoja['!ref'] };\n    // Resumen por estado\n    const porEstado = {};\n    clientes.forEach(c => {\n      const e = c['ESTADO'] || '(sin datos)';\n      porEstado[e] = porEstado[e] || { 'Estado': e, 'Clientes': 0, 'Activos': 0, 'Compraron en 12 meses': 0 };\n      porEstado[e]['Clientes']++;\n      if (c['Estatus'] === 'Activo') porEstado[e]['Activos']++;\n      if (c['Días sin comprar'] !== '' && c['Días sin comprar'] <= 365) porEstado[e]['Compraron en 12 meses']++;\n    });\n    const resumen = Object.values(porEstado).sort((a, b) => b['Clientes'] - a['Clientes']);\n    const hojaRes = XLSX.utils.json_to_sheet(resumen);\n    hojaRes['!cols'] = [{ wch: 26 }, { wch: 10 }, { wch: 10 }, { wch: 22 }];\n    const libro = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(libro, hoja, 'Clientes');\n    XLSX.utils.book_append_sheet(libro, hojaRes, 'Por estado');\n    XLSX.writeFile(libro, `clientes_microsip_${new Date().toISOString().slice(0,10)}.xlsx`);\n  } catch (e) {\n    alert(e.message || 'No se pudo consultar Microsip.');\n  } finally {\n    if (btn) { btn.disabled = false; btn.textContent = original; }\n  }\n}\n\n// Excel de los artículos de Microsip que no tienen clasificador de MARCA\n"
